SELECT s.device, t.avg_duration_sec, t.add_to_cart_count FROM sessions s LEFT JOIN (SELECT session_id, AVG(duration_sec) AS avg_duration_sec, SUM(CASE WHEN event_type = 'add_to_cart' THEN 1 ELSE 0 END) AS add_to_cart_count FROM web_events GROUP BY session_id) t ON s.id = t.session_id WHERE t.add_to_cart_count >= 54 ORDER BY add_to_cart_count DESC
